import{z as i,x as d,o as E,c,q as t,j as l,D as n,d as o,s as r,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Nonce 误用与重放","description":"","frontmatter":{"title":"Nonce 误用与重放","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nonce-misuse.md","filePath":"cs/nonce-misuse.md","lastUpdated":1791413859000}'),p={name:"cs/nonce-misuse.md"};function B(D,a,m,h,u,C){const s=d("Mermaid");return E(),c("div",null,[a[2]||(a[2]=t('<h1 id="nonce-误用与重放" tabindex="-1">Nonce 误用与重放 <a class="header-anchor" href="#nonce-误用与重放" aria-label="Permalink to &quot;Nonce 误用与重放&quot;">​</a></h1><div class="epigraph"><p>Nonce 不是密钥，却必须在同一密钥下唯一。复用一次，CTR/GCM 的证明就退出；重放则是把合法密文再播一次，完整标签拦不住「旧消息再来」。</p><footer>—— 据 NIST SP 800-38D 对 IV 合同；Rogaway 对 nonce-based 加密；Katz and Lindell 整理</footer></div><p>上一课<a href="/cs/aead-gcm-internals">GCM 内部</a>把保密与标签收成一次调用。缺口是<strong>状态</strong>：nonce 谁发、如何不重复、重放是否算攻击。主干对称课已警告复用是灾难；本课把它从旁注升为主题。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>GCM 在 nonce 复用下会泄漏密钥流并伤及 GHASH 密钥——本课陈述性质，不给恢复步骤。随机 96 比特 nonce 碰撞遵循生日界，消息量大时要换计数器或密钥。重放：敌手重发旧的合法 AEAD 对，标签仍对；要会话层新鲜性（序号、时间窗、<a href="/cs/auth-protocol">认证协议</a>里的 nonce）。</p><h3 id="误用抵抗不是默认" tabindex="-1">误用抵抗不是默认 <a class="header-anchor" href="#误用抵抗不是默认" aria-label="Permalink to &quot;误用抵抗不是默认&quot;">​</a></h3><p>SIV 等误用抵抗模式改变合同：重复 nonce 泄漏相等性而非密钥。不要假设库「已经防呆」。</p><p><span class="marginnote">术语翻译：SIV（合成 IV）就是把 nonce 不再交给发送方自由选择、而是从明文和密钥派生出来的手段，来做「即使复用也不泄漏密钥」的事；代价是复用时会泄漏「两条明文完全相同」这一事实。</span></p><p><span class="marginnote">Rogaway 的 nonce-based 对称加密把唯一性写进游戏。TLS 记录序号、SSH 序号都是协议层计数器。本课不提供复用下的代数求解。</span></p><p><span class="marginnote">常见误区：「标签验证通过」等于「消息是新的」。实际上标签只证明这段密文出自持有密钥的某次加密，不证明它此刻是第一次到达——后者叫新鲜性，要靠序号或时间窗单独建立。</span></p><p><span class="marginnote">直觉类比：重放就像拿昨天的有效门票今天再进一次场。票本身是真的（标签能验证通过），检票员要拒收，靠的不是验票，而是核对「这个场次号还没被用过」——会话序号干的就是这件事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分两条失败：生成端复用；网络重放。对策：计数器 nonce、密钥分级、每连接新密钥、应用层幂等与序号。AEAD 不替代这些。</p>',14)),(E(),l(A,null,{default:n(()=>[r(s,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E5%90%8C%E4%B8%80%E5%AF%86%E9%92%A5%22%5D%20--%3E%20NQ%5B%22nonce%20%E5%BF%85%E9%A1%BB%E5%94%AF%E4%B8%80%22%5D%0A%20%20NQ%20--%3E%20OK%5B%22%E5%90%88%E5%90%8C%E5%86%85%3A%20AEAD%20%E8%AF%81%E6%98%8E%E6%9C%89%E6%95%88%22%5D%0A%20%20NQ%20--%3E%20BAD%5B%22%E5%A4%8D%E7%94%A8%3A%20%E8%AF%81%E6%98%8E%E9%80%80%E5%87%BA%22%5D%0A%20%20OK%20--%3E%20RP%5B%22%E9%87%8D%E6%94%BE%E4%BB%8D%E9%9C%80%E5%BA%8F%E5%8F%B7%2F%E7%AA%97%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"计算安全的证明都有前提。Nonce 是前提里的状态变量。重放是完整性标签范围外的会话语义：标签说「这是某次合法封装」，不说「这是此刻该接受的第一次」。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：96 比特随机 nonce 的碰撞概率约为 \\(q^2/2^{97}\\)（\\(q\\) 为加密次数）。代入 \\(q=2^{32}\\)（约 43 亿条），概率约 \\(2^{-33}\\)，看似很小，但 NIST 干脆规定每个密钥的 GCM 调用不超过 \\(2^{32}\\) 次，把风险钉死在界内——这就是「消息量大时要换密钥」的出处。")],-1)),(E(),l(A,null,{default:n(()=>[r(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E5%AF%86%E9%92%A5%E4%B8%8B%E9%80%89%E5%93%AA%E7%A7%8D%20nonce%20%E7%AD%96%E7%95%A5%3F%22%5D%20--%3E%20R%5B%22%E9%9A%8F%E6%9C%BA%2096%20%E6%AF%94%E7%89%B9%22%5D%0A%20%20Q%20--%3E%20C%5B%22%E5%8D%95%E8%B0%83%E8%AE%A1%E6%95%B0%E5%99%A8%22%5D%0A%20%20Q%20--%3E%20S%5B%22SIV%20%E8%AF%AF%E7%94%A8%E6%8A%B5%E6%8A%97%22%5D%0A%20%20R%20--%3E%20R1%5B%22%E9%9D%A0%E7%94%9F%E6%97%A5%E7%95%8C%E7%BA%A6%E6%9D%9F%E7%94%A8%E9%87%8F%2C%20%E5%A4%8D%E7%94%A8%E5%8D%B3%E7%81%BE%E9%9A%BE%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E6%9C%AC%E5%9C%B0%E4%B8%8D%E9%87%8D%E5%A4%8D%2C%20%E4%BD%86%E9%87%8D%E5%90%AF%E8%A6%81%E6%81%A2%E5%A4%8D%E8%AE%A1%E6%95%B0%22%5D%0A%20%20S%20--%3E%20S1%5B%22%E5%A4%8D%E7%94%A8%E5%8F%AA%E6%B3%84%E6%BC%8F%E6%98%8E%E6%96%87%E7%9B%B8%E7%AD%89%E6%80%A7%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把随机数硬件写成 CSPRNG 课（更后）。填充预言是另一条主动敌手：下一课说明为何「解密失败如何返回」会变成明文泄漏通道。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GCM 合同的核心是 nonce 唯一。</li><li>复用破坏保密与认证密钥；重放要序号。</li><li>误用抵抗模式是另一合同，不是静默修复。</li><li>下一课：填充与错误信息造成的预言机。</li><li>出处：NIST SP 800-38D；Rogaway；Katz and Lindell；对照 RFC 8446 记录序号。</li></ul>',4))])}const _=i(p,[["render",B]]);export{f as __pageData,_ as default};
